CREATE POLICY "Round students can view round-attached audio playlists" ON public.audio_playlists FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.program_round_playlists prp JOIN public.course_enrollments ce ON ce.round_id = prp.round_id WHERE prp.playlist_type <> 'video' AND prp.playlist_id = audio_playlists.id AND ce.user_id = auth.uid() AND ce.status = 'active'));
CREATE POLICY "Round students can view round-attached playlist items" ON public.audio_playlist_items FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.program_round_playlists prp JOIN public.course_enrollments ce ON ce.round_id = prp.round_id WHERE prp.playlist_type <> 'video' AND prp.playlist_id = audio_playlist_items.playlist_id AND ce.user_id = auth.uid() AND ce.status = 'active'));
CREATE POLICY "Round students can view round-attached audio content" ON public.audio_content FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.audio_playlist_items api JOIN public.program_round_playlists prp ON prp.playlist_id = api.playlist_id AND prp.playlist_type <> 'video' JOIN public.course_enrollments ce ON ce.round_id = prp.round_id WHERE api.audio_id = audio_content.id AND ce.user_id = auth.uid() AND ce.status = 'active'));